require __DIR__.'/config.php';$errors=[];$v=$_POST;$branches=[];$types=[];
try{$branches=db()->query("SELECT branch_id,branch_name FROM branches WHERE status='active' ORDER BY branch_name")->fetchAll();$types=db()->query('SELECT account_type_id,type_name,minimum_balance FROM account_types ORDER BY type_name')->fetchAll();}catch(Throwable $x){$errors[]='Applications are temporarily unavailable. Please try again later.';}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$f=fn($k)=>trim((string)($v[$k]??''));foreach(['full_name'=>'Full name','father_name'=>"Father's name",'mother_name'=>"Mother's name",'date_of_birth'=>'Date of birth','profession'=>'Profession','source_of_fund'=>'Source of funds','phone'=>'Phone','id_number'=>'Identity number','address_line'=>'Street address','district'=>'District','email'=>'Email','password'=>'Password'] as $k=>$label)if($f($k)==='')$errors[]="$label is required.";if(!filter_var($f('email'),FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if(strlen((string)($v['password']??''))<10)$errors[]='Password must be at least 10 characters.';if(($v['password']??'')!==($v['password_confirm']??''))$errors[]='Passwords do not match.';if(!in_array($f('gender'),['male','female','other'],true))$errors[]='Select a valid gender.';if(!in_array($f('id_type'),['nid','passport','birth_certificate','driving_license','other'],true))$errors[]='Select a valid identity type.';if(!preg_match('/^[0-9+() -]{7,20}$/',$f('phone')))$errors[]='Enter a valid phone number.';if(!$errors){try{$q=db()->prepare('SELECT COUNT(*) FROM customers WHERE phone=? OR email=? OR id_number=?');$q->execute([$f('phone'),strtolower($f('email')),$f('id_number')]);if((int)$q->fetchColumn())$errors[]='That phone, email, or identity number is already registered.';}catch(Throwable $x){$errors[]='Applications are temporarily unavailable. Please try again later.';}}
if(!$errors){$pdo=db();try{$pdo->beginTransaction();$branch=(int)$f('branch_id');$type=(int)$f('account_type_id');$check=$pdo->prepare("SELECT branch_id FROM branches WHERE branch_id=? AND status='active'");$check->execute([$branch]);if(!$check->fetch())throw new RuntimeException();$check=$pdo->prepare('SELECT account_type_id FROM account_types WHERE account_type_id=?');$check->execute([$type]);if(!$check->fetch())throw new RuntimeException();$s=$pdo->prepare("INSERT INTO customers (cif_number,full_name,full_name_bn,father_name,mother_name,spouse_name,date_of_birth,gender,nationality,profession,monthly_income,source_of_fund,tin_number,phone,email,id_type,id_number,branch_id,status,kyc_status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'active','pending')");$s->execute([(string)random_int(10000000,99999999),$f('full_name'),$f('full_name_bn')?:null,$f('father_name'),$f('mother_name'),$f('spouse_name')?:null,$f('date_of_birth'),$f('gender'),$f('nationality')?:'Bangladeshi',$f('profession'),$f('monthly_income')!==''?$f('monthly_income'):null,$f('source_of_fund'),$f('tin_number')?:null,$f('phone'),strtolower($f('email')),$f('id_type'),$f('id_number'),$branch]);$cid=(int)$pdo->lastInsertId();$a=$pdo->prepare("INSERT INTO addresses (customer_id,address_type,address_line,post_office,thana,district,postal_code) VALUES (?,'present',?,?,?,?,?)");$a->execute([$cid,$f('address_line'),$f('post_office')?:null,$f('thana')?:null,$f('district'),$f('postal_code')?:null]);$u=$pdo->prepare("INSERT INTO users (password_hash,linked_customer_id,status) VALUES (?,?,'active')");$u->execute([password_hash((string)$v['password'],PASSWORD_DEFAULT),$cid]);$uid=(int)$pdo->lastInsertId();$role=$pdo->query("SELECT role_id FROM roles WHERE role_name='Customer'")->fetchColumn();if(!$role)throw new RuntimeException();$pdo->prepare('INSERT INTO user_roles (user_id,role_id) VALUES (?,?)')->execute([$uid,$role]);$num='BE'.str_pad((string)$branch,3,'0',STR_PAD_LEFT).random_int(1000000000,9999999999);$a=$pdo->prepare("INSERT INTO accounts (account_number,account_title,account_type_id,branch_id,balance,status,opening_date) VALUES (?,?,?,?,0,'pending',CURDATE())");$a->execute([$num,$f('full_name'),$type,$branch]);$aid=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO account_holders (account_id,customer_id,holder_role,operating_mode) VALUES (?,?,'primary','single')")->execute([$aid,$cid]);audit($uid,'REGISTER','customers',$cid,'Online customer account application submitted');notify_account_application($pdo,$cid,$aid);$pdo->commit();flash('Application received. Your account is pending staff KYC review. You can now sign in.');go('login.php');}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$errors[]='We could not submit your application. Check the details and try again.';}}}
render_start('Open an account');?><section class="page-heading"><div class="eyebrow dark">Start with BankEase</div><h1>Open your account</h1><p>Your account will remain pending until staff verify your KYC information.</p></section><section class="register-card"><?php if($errors):?><div class="notice error"><strong>Please review:</strong><ul><?php foreach(array_unique($errors) as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" class="form-grid"><?=csrf()?><?php $fields=[['full_name','Full name'],['full_name_bn','Full name (Bangla)',null,true],['father_name',"Father's name"],['mother_name',"Mother's name"],['spouse_name',"Spouse's name",null,true],['date_of_birth','Date of birth','date'],['nationality','Nationality',null,true],['profession','Profession'],['monthly_income','Monthly income (BDT)','number',true],['source_of_fund','Source of funds'],['tin_number','TIN number',null,true],['phone','Mobile number','tel'],['id_number','Identity number'],['email','Email','email'],['address_line','Street / village address'],['post_office','Post office',null,true],['thana','Thana',null,true],['district','District'],['postal_code','Postal code',null,true],['password','Create password','password'],['password_confirm','Confirm password','password']];foreach($fields as [$name,$label,$type,$optional]){$type=$type??'text';?><div class="field"><label for="<?=e($name)?>"><?=e($label)?><?=$optional?' (optional)':''?></label><input id="<?=e($name)?>" name="<?=e($name)?>" type="<?=e($type)?>" value="<?=e(str_contains($type,'password')?'':($v[$name]??''))?>" <?=$optional?'':'required'?> <?=$name==='monthly_income'?'min="0" step="0.01"':''?>></div><?php }?><div class="field"><label for="gender">Gender</label><select id="gender" name="gender" required><option value="">Choose…</option><?php foreach(['male'=>'Male','female'=>'Female','other'=>'Other'] as $k=>$label):?><option value="<?=$k?>" <?=($v['gender']??'')===$k?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="field"><label for="id_type">Identity type</label><select id="id_type" name="id_type" required><option value="">Choose…</option><?php foreach(['nid'=>'NID','passport'=>'Passport','birth_certificate'=>'Birth certificate','driving_license'=>'Driving license','other'=>'Other'] as $k=>$label):?><option value="<?=$k?>" <?=($v['id_type']??'')===$k?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="field"><label for="branch_id">Preferred branch</label><select id="branch_id" name="branch_id" required><option value="">Choose branch…</option><?php foreach($branches as $b):?><option value="<?=$b['branch_id']?>" <?=($v['branch_id']??'')==$b['branch_id']?'selected':''?>><?=e($b['branch_name'])?></option><?php endforeach;?></select></div><div class="field"><label for="account_type_id">Account type</label><select id="account_type_id" name="account_type_id" required><option value="">Choose type…</option><?php foreach($types as $t):?><option value="<?=$t['account_type_id']?>" <?=($v['account_type_id']??'')==$t['account_type_id']?'selected':''?>><?=e($t['type_name'])?> · min BDT <?=e(number_format((float)$t['minimum_balance'],2))?></option><?php endforeach;?></select></div><div class="full"><button class="button navy" type="submit">Submit account application</button></div></form></section><?php render_end();?>
